from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one replacement, found {count}")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")


replace_once(
    "sentinel/schema.py",
    '''    "sentinel_observation_provenance",\n})''',
    '''    "sentinel_observation_provenance",\n    "sentinel_trial_strategy_evidence",\n})''',
)

replace_once(
    "sentinel/schema.py",
    '''    """CREATE TABLE IF NOT EXISTS sentinel_observation_provenance (\n        observation_seq   BIGINT PRIMARY KEY REFERENCES sentinel_observations(seq),\n        broker            TEXT        NOT NULL,\n        broker_account_id TEXT        NOT NULL,\n        observed_at       TIMESTAMPTZ NOT NULL)""",\n\n    # A broker response being durable is not proof that it was PROCESSED.''',
    '''    """CREATE TABLE IF NOT EXISTS sentinel_observation_provenance (\n        observation_seq   BIGINT PRIMARY KEY REFERENCES sentinel_observations(seq),\n        broker            TEXT        NOT NULL,\n        broker_account_id TEXT        NOT NULL,\n        observed_at       TIMESTAMPTZ NOT NULL)""",\n\n    # Per-session STRATEGY evidence for the forward paper trial.  Plans, broker\n    # observations, commands and fills already have separate durable journals;\n    # this table preserves the strategy-side facts that would otherwise be\n    # overwritten when SessionState advances to the next close.\n    """CREATE TABLE IF NOT EXISTS sentinel_trial_strategy_evidence (\n        session             DATE PRIMARY KEY,\n        data_version        BIGINT      NOT NULL,\n        state_sha256        TEXT        NOT NULL CHECK (\n            state_sha256 ~ '^[0-9a-f]{64}$'),\n        strategy_identity   JSONB       NOT NULL,\n        decision            JSONB       NOT NULL,\n        evidence            JSONB       NOT NULL,\n        recent_leadership   JSONB,\n        ldrc                JSONB,\n        payload_sha256      TEXT        NOT NULL CHECK (\n            payload_sha256 ~ '^[0-9a-f]{64}$'),\n        recorded_at         TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp())""",\n    """CREATE OR REPLACE FUNCTION sentinel_refuse_trial_evidence_mutation()\n        RETURNS trigger LANGUAGE plpgsql AS $$\n        BEGIN\n          RAISE EXCEPTION 'sentinel_trial_strategy_evidence is append-only';\n        END; $$""",\n    """DO $$\n        BEGIN\n          IF NOT EXISTS (\n              SELECT 1 FROM pg_trigger\n               WHERE tgname = 'sentinel_trial_strategy_evidence_append_only'\n                 AND tgrelid = 'sentinel_trial_strategy_evidence'::regclass\n                 AND NOT tgisinternal) THEN\n            CREATE TRIGGER sentinel_trial_strategy_evidence_append_only\n              BEFORE UPDATE OR DELETE ON sentinel_trial_strategy_evidence\n              FOR EACH ROW EXECUTE FUNCTION\n                sentinel_refuse_trial_evidence_mutation();\n          END IF;\n        END $$""",\n\n    # A broker response being durable is not proof that it was PROCESSED.''',
)

replace_once(
    "sentinel/core/catchup.py",
    '''        state = advance_state(conn, session.isoformat(), state)\n        _mark_processed(conn, session, state)\n        # Historical sessions become durable one at a time.''',
    '''        state = advance_state(conn, session.isoformat(), state)\n        _mark_processed(conn, session, state)\n        # Preserve the exact canonical strategy facts in the SAME transaction\n        # as the cursor/state. Generic research/test seams are deliberately\n        # ignored by the recorder; only a valid production SessionState can\n        # enter the forward-trial evidence ledger.\n        from sentinel import trial_evidence\n        trial_evidence.record_strategy_session(\n            conn, session=session.isoformat(), state=state)\n        # Historical sessions become durable one at a time.''',
)

Path("sentinel/trial_evidence.py").write_text('''"""Append-only per-session strategy evidence for the forward paper trial.\n\nThis is observability, never strategy authority.  It records the canonical\nSessionState that has already been computed; no value from this table is read\nback into Wealth Core, Sentinel, Concordance, projection or execution.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom typing import Mapping\n\n\nclass TrialEvidenceConflict(RuntimeError):\n    """A session already has different retained strategy evidence."""\n\n\ndef _canonical_bytes(value) -> bytes:\n    return json.dumps(\n        value, sort_keys=True, separators=(",", ":"), allow_nan=False\n    ).encode("utf-8")\n\n\ndef _hash(value) -> str:\n    return hashlib.sha256(_canonical_bytes(value)).hexdigest()\n\n\ndef _canonical_production_state(state):\n    if not isinstance(state, Mapping):\n        return None\n    try:\n        # Lazy import avoids making the generic catch-up coordinator depend on\n        # production at module load time.  A generic test/research seam that is\n        # merely JSON-serialisable is intentionally not trial evidence.\n        from sentinel.core.production import SessionState\n        return SessionState.from_dict(state)\n    except (KeyError, TypeError, ValueError):\n        return None\n\n\ndef record_strategy_session(conn, *, session: str, state) -> bool:\n    """Retain one canonical production strategy close without committing.\n\n    Identical replay is idempotent. A different payload for an already-retained\n    session is corruption and refuses the surrounding transaction. PostgreSQL\n    additionally rejects UPDATE/DELETE so application bugs cannot rewrite the\n    historical explanation later.\n    """\n    canonical = _canonical_production_state(state)\n    if canonical is None:\n        return False\n    if canonical.last_processed_session != session:\n        raise TrialEvidenceConflict(\n            "canonical strategy state session differs from evidence session")\n    if canonical.data_version is None:\n        raise TrialEvidenceConflict(\n            "canonical strategy state has no publication data_version")\n    if not isinstance(canonical.last_decision, Mapping):\n        raise TrialEvidenceConflict(\n            "canonical strategy state has no decision evidence")\n    if not isinstance(canonical.last_evidence, Mapping):\n        raise TrialEvidenceConflict(\n            "canonical strategy state has no observation evidence")\n\n    payload = {\n        "session": session,\n        "data_version": int(canonical.data_version),\n        "state_sha256": canonical.state_hash,\n        "strategy_identity": canonical.strategy_identity,\n        "decision": canonical.last_decision,\n        "evidence": canonical.last_evidence,\n        "recent_leadership": canonical.recent_leadership,\n        "ldrc": canonical.ldrc,\n    }\n    payload_sha256 = _hash(payload)\n    with conn.cursor() as cur:\n        cur.execute(\n            "INSERT INTO sentinel_trial_strategy_evidence "\n            "(session,data_version,state_sha256,strategy_identity,decision,"\n            " evidence,recent_leadership,ldrc,payload_sha256) "\n            "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s) "\n            "ON CONFLICT (session) DO NOTHING",\n            (session, payload["data_version"], payload["state_sha256"],\n             json.dumps(payload["strategy_identity"], sort_keys=True),\n             json.dumps(payload["decision"], sort_keys=True),\n             json.dumps(payload["evidence"], sort_keys=True),\n             (json.dumps(payload["recent_leadership"], sort_keys=True)\n              if payload["recent_leadership"] is not None else None),\n             (json.dumps(payload["ldrc"], sort_keys=True)\n              if payload["ldrc"] is not None else None),\n             payload_sha256),\n        )\n        inserted = cur.rowcount == 1\n        if not inserted:\n            cur.execute(\n                "SELECT data_version,state_sha256,strategy_identity,decision,"\n                " evidence,recent_leadership,ldrc,payload_sha256 "\n                "FROM sentinel_trial_strategy_evidence WHERE session=%s",\n                (session,),\n            )\n            row = cur.fetchone()\n            if row is None:\n                raise TrialEvidenceConflict(\n                    "trial evidence conflict disappeared during verification")\n            retained = {\n                "session": session,\n                "data_version": int(row[0]),\n                "state_sha256": str(row[1]),\n                "strategy_identity": row[2],\n                "decision": row[3],\n                "evidence": row[4],\n                "recent_leadership": row[5],\n                "ldrc": row[6],\n            }\n            if str(row[7]) != payload_sha256 or _hash(retained) != payload_sha256:\n                raise TrialEvidenceConflict(\n                    f"session {session} already has different strategy evidence")\n    return True\n\n\ndef load_strategy_session(conn, session: str) -> dict | None:\n    """Read retained evidence for inspection/reporting; never strategy logic."""\n    with conn.cursor() as cur:\n        cur.execute(\n            "SELECT data_version,state_sha256,strategy_identity,decision,evidence,"\n            " recent_leadership,ldrc,payload_sha256,recorded_at "\n            "FROM sentinel_trial_strategy_evidence WHERE session=%s",\n            (session,),\n        )\n        row = cur.fetchone()\n    if row is None:\n        return None\n    result = {\n        "session": session, "data_version": int(row[0]),\n        "state_sha256": str(row[1]), "strategy_identity": row[2],\n        "decision": row[3], "evidence": row[4],\n        "recent_leadership": row[5], "ldrc": row[6],\n        "payload_sha256": str(row[7]), "recorded_at": row[8],\n    }\n    check = {key: result[key] for key in (\n        "session", "data_version", "state_sha256", "strategy_identity",\n        "decision", "evidence", "recent_leadership", "ldrc")}\n    if _hash(check) != result["payload_sha256"]:\n        raise TrialEvidenceConflict(\n            f"retained strategy evidence hash mismatch for {session}")\n    return result\n\n\n__all__ = [\n    "TrialEvidenceConflict", "load_strategy_session",\n    "record_strategy_session",\n]\n''', encoding="utf-8")

Path("tests/sentinel/test_issue209_trial_strategy_evidence.py").write_text('''import json\n\nimport pytest\n\nfrom sentinel import trial_evidence\nfrom sentinel.controller.frozen_rule import load as load_controller\nfrom sentinel.controller.machine import Controller\nfrom sentinel.core.decision import runtime_strategy_identity\nfrom sentinel.core.production import SessionState\nfrom sentinel.feed import store as feed_store\nfrom tests.support.postgres import _EphemeralPostgres, drop_public_tables\n\n\n@pytest.fixture(scope="module")\ndef pg():\n    try:\n        server = _EphemeralPostgres(); server.start()\n    except Exception as exc:  # noqa: BLE001\n        pytest.skip(f"ephemeral Postgres unavailable: {exc}")\n    try:\n        yield server\n    finally:\n        server.stop()\n\n\n@pytest.fixture()\ndef conn(pg):\n    c = feed_store.connect(pg.sync_dsn)\n    drop_public_tables(c)\n    feed_store.ensure_schema(c)\n    from sentinel import schema\n    schema.ensure_schema(c)\n    yield c\n    c.close()\n\n\ndef canonical_state(session="2026-08-20"):\n    config = load_controller()\n    state = SessionState.fresh(\n        starting_cash=100000.0, controller=Controller(config),\n        strategy_identity=runtime_strategy_identity(config))\n    state.last_processed_session = session\n    state.data_version = 7\n    state.last_decision = {"session": session, "target_core_exposure": 1.0}\n    state.last_evidence = {"observation": {"session": session, "shadow_nav": 100000.0}}\n    return state.to_dict()\n\n\ndef test_generic_catchup_state_is_not_misrepresented_as_strategy_evidence(conn):\n    assert trial_evidence.record_strategy_session(\n        conn, session="2026-08-20", state={"sessions": 1}) is False\n    with conn.cursor() as cur:\n        cur.execute("SELECT COUNT(*) FROM sentinel_trial_strategy_evidence")\n        assert cur.fetchone()[0] == 0\n\n\ndef test_canonical_strategy_evidence_is_idempotent_and_hash_verified(conn):\n    state = canonical_state()\n    assert trial_evidence.record_strategy_session(\n        conn, session="2026-08-20", state=state) is True\n    assert trial_evidence.record_strategy_session(\n        conn, session="2026-08-20", state=state) is True\n    row = trial_evidence.load_strategy_session(conn, "2026-08-20")\n    assert row["state_sha256"] == SessionState.from_dict(state).state_hash\n    assert row["decision"]["target_core_exposure"] == 1.0\n    with conn.cursor() as cur:\n        cur.execute("SELECT COUNT(*) FROM sentinel_trial_strategy_evidence")\n        assert cur.fetchone()[0] == 1\n\n\ndef test_same_session_different_strategy_evidence_refuses(conn):\n    state = canonical_state()\n    trial_evidence.record_strategy_session(\n        conn, session="2026-08-20", state=state)\n    changed = json.loads(json.dumps(state))\n    changed["last_decision"]["target_core_exposure"] = 0.55\n    with pytest.raises(trial_evidence.TrialEvidenceConflict, match="different"):\n        trial_evidence.record_strategy_session(\n            conn, session="2026-08-20", state=changed)\n    conn.rollback()\n\n\ndef test_postgres_refuses_update_and_delete_of_trial_evidence(conn):\n    state = canonical_state()\n    trial_evidence.record_strategy_session(\n        conn, session="2026-08-20", state=state)\n    conn.commit()\n    with pytest.raises(Exception, match="append-only"):\n        with conn.cursor() as cur:\n            cur.execute(\n                "UPDATE sentinel_trial_strategy_evidence SET data_version=8 "\n                "WHERE session='2026-08-20'")\n    conn.rollback()\n    with pytest.raises(Exception, match="append-only"):\n        with conn.cursor() as cur:\n            cur.execute(\n                "DELETE FROM sentinel_trial_strategy_evidence "\n                "WHERE session='2026-08-20'")\n    conn.rollback()\n''', encoding="utf-8")
